    bool isWhitespace(unsigned char ch)
    {
        return ch == ' ' || ch == '\t' || ch == '\n' || ch == '\r';
    }

    gocpp::string stripTrailingWhitespace(gocpp::string s)
    {
        auto i = len(s);
        for(; i > 0 && isWhitespace(s[i - 1]); )
        {
            i--;
        }
        return s.make_slice(0, i);
    }

    // Text returns the text of the comment.
    // Comment markers (//, /*, and */), the first space of a line comment, and
    // leading and trailing empty lines are removed.
    // Comment directives like "//line" and "//go:noinline" are also removed.
    // Multiple empty lines are reduced to one, and trailing space on lines is trimmed.
    // Unless the result is empty, it is newline-terminated.
    gocpp::string rec::Text(CommentGroup* g)
    {
        if(g == nullptr)
        {
            return ""_s;
        }
        auto comments = gocpp::make(gocpp::Tag<gocpp::slice<gocpp::string>>(), len(g->List));
        for(auto [i, c] : g->List)
        {
            comments[i] = c->Text;
        }

        // most comments are less than 10 lines
        auto lines = gocpp::make(gocpp::Tag<gocpp::slice<gocpp::string>>(), 0, 10);
        for(auto [gocpp_ignored, c] : comments)
        {
            // Remove comment markers.
            // The parser has given us exactly the comment text.
            //Go switch emulation
            {
                auto condition = c[1];
                int conditionId = -1;
                if(condition == '/') { conditionId = 0; }
                else if(condition == '*') { conditionId = 1; }
                switch(conditionId)
                {
                    case 0:
                        // -style comment (no newline at the end)
                        c = c.make_slice(2);
                        if(len(c) == 0)
                        {
                            // empty line
                            break;
                        }
                        if(c[0] == ' ')
                        {
                            // strip first space - required for Example tests
                            c = c.make_slice(1);
                            break;
                        }
                        if(isDirective(c))
                        {
                            // Ignore //go:noinline, //line, and so on.
                            continue;
                        }
                        break;
                    case 1:
                        // -style comment
                        c = c.make_slice(2, len(c) - 2);
                        break;
                }
            }

            // Split on newlines.
            auto cl = strings::Split(c, "\n"_s);

            // Walk lines, stripping trailing white space and adding to list.
            for(auto [gocpp_ignored, l] : cl)
            {
                lines = append(lines, stripTrailingWhitespace(l));
            }
        }

        // Remove leading blank lines; convert runs of
        // interior blank lines to a single blank line.
        auto n = 0;
        for(auto [gocpp_ignored, line] : lines)
        {
            if(line != ""_s || n > 0 && lines[n - 1] != ""_s)
            {
                lines[n] = line;
                n++;
            }
        }
        lines = lines.make_slice(0, n);

        // Add final "" entry to get trailing newline from Join.
        if(n > 0 && lines[n - 1] != ""_s)
        {
            lines = append(lines, ""_s);
        }

        return mocklib::StringsJoin(lines, "\n"_s);
    }

    // isDirective reports whether c is a comment directive.
    // This code is also in go/printer.
    bool isDirective(gocpp::string c)
    {
        // "//line " is a line directive.
        // "//extern " is for gccgo.
        // "//export " is for cgo.
        // (The // has been removed.)
        if(strings::HasPrefix(c, "line "_s) || strings::HasPrefix(c, "extern "_s) || strings::HasPrefix(c, "export "_s))
        {
            return true;
        }

        // "//[a-z0-9]+:[a-z0-9]"
        // (The // has been removed.)
        auto colon = strings::Index(c, ":"_s);
        if(colon <= 0 || colon + 1 >= len(c))
        {
            return false;
        }
        for(auto i = 0; i <= colon + 1; i++)
        {
            if(i == colon)
            {
                continue;
            }
            auto b = c[i];
            if(! ('a' <= b && b <= 'z' || '0' <= b && b <= '9'))
            {
                return false;
            }
        }
        return true;
    }

