    token::Pos rec::Pos(FieldList* f)
    {
        if(rec::IsValid(gocpp::recv(f->Opening)))
        {
            return f->Opening;
        }
        // the list should not be empty in this case;
        // be conservative and guard against bad ASTs
        if(len(f->List) > 0)
        {
            return rec::Pos(gocpp::recv(f->List[0]));
        }
        return token::NoPos;
    }

    token::Pos rec::End(FieldList* f)
    {
        if(rec::IsValid(gocpp::recv(f->Closing)))
        {
            return f->Closing + 1;
        }
        // the list should not be empty in this case;
        // be conservative and guard against bad ASTs
        if(auto n = len(f->List); n > 0)
        {
            return rec::End(gocpp::recv(f->List[n - 1]));
        }
        return token::NoPos;
    }

    // NumFields returns the number of parameters or struct fields represented by a [FieldList].
    int rec::NumFields(FieldList* f)
    {
        auto n = 0;
        if(f != nullptr)
        {
            for(auto [gocpp_ignored, g] : f->List)
            {
                auto m = len(g->Names);
                if(m == 0)
                {
                    m = 1;
                }
                n += m;
            }
        }
        return n;
    }

