    token::Pos rec::Pos(BadExpr* x)
    {
        return x->From;
    }

    token::Pos rec::Pos(Ident* x)
    {
        return x->NamePos;
    }

    token::Pos rec::Pos(Ellipsis* x)
    {
        return x->Ellipsis;
    }

    token::Pos rec::Pos(BasicLit* x)
    {
        return x->ValuePos;
    }

    token::Pos rec::Pos(FuncLit* x)
    {
        return rec::Pos(gocpp::recv(x->Type));
    }

    token::Pos rec::Pos(CompositeLit* x)
    {
        if(x->Type != nullptr)
        {
            return rec::Pos(gocpp::recv(x->Type));
        }
        return x->Lbrace;
    }

    token::Pos rec::Pos(ParenExpr* x)
    {
        return x->Lparen;
    }

    token::Pos rec::Pos(SelectorExpr* x)
    {
        return rec::Pos(gocpp::recv(x->X));
    }

    token::Pos rec::Pos(IndexExpr* x)
    {
        return rec::Pos(gocpp::recv(x->X));
    }

    token::Pos rec::Pos(IndexListExpr* x)
    {
        return rec::Pos(gocpp::recv(x->X));
    }

    token::Pos rec::Pos(SliceExpr* x)
    {
        return rec::Pos(gocpp::recv(x->X));
    }

    token::Pos rec::Pos(TypeAssertExpr* x)
    {
        return rec::Pos(gocpp::recv(x->X));
    }

    token::Pos rec::Pos(CallExpr* x)
    {
        return rec::Pos(gocpp::recv(x->Fun));
    }

    token::Pos rec::Pos(StarExpr* x)
    {
        return x->Star;
    }

    token::Pos rec::Pos(UnaryExpr* x)
    {
        return x->OpPos;
    }

    token::Pos rec::Pos(BinaryExpr* x)
    {
        return rec::Pos(gocpp::recv(x->X));
    }

    token::Pos rec::Pos(KeyValueExpr* x)
    {
        return rec::Pos(gocpp::recv(x->Key));
    }

    token::Pos rec::Pos(ArrayType* x)
    {
        return x->Lbrack;
    }

    token::Pos rec::Pos(StructType* x)
    {
        return x->Struct;
    }

    token::Pos rec::Pos(FuncType* x)
    {
        if(rec::IsValid(gocpp::recv(x->Func)) || x->Params == nullptr)
        {
            // see issue 3870
            return x->Func;
        }
        // interface method declarations have no "func" keyword
        return rec::Pos(gocpp::recv(x->Params));
    }

    token::Pos rec::Pos(InterfaceType* x)
    {
        return x->Interface;
    }

    token::Pos rec::Pos(MapType* x)
    {
        return x->Map;
    }

    token::Pos rec::Pos(ChanType* x)
    {
        return x->Begin;
    }

    token::Pos rec::End(BadExpr* x)
    {
        return x->To;
    }

    token::Pos rec::End(Ident* x)
    {
        return token::Pos(int(x->NamePos) + len(x->Name));
    }

    token::Pos rec::End(Ellipsis* x)
    {
        if(x->Elt != nullptr)
        {
            return rec::End(gocpp::recv(x->Elt));
        }
        // len("...")
        return x->Ellipsis + 3;
    }

    token::Pos rec::End(BasicLit* x)
    {
        return token::Pos(int(x->ValuePos) + len(x->Value));
    }

    token::Pos rec::End(FuncLit* x)
    {
        return rec::End(gocpp::recv(x->Body));
    }

    token::Pos rec::End(CompositeLit* x)
    {
        return x->Rbrace + 1;
    }

    token::Pos rec::End(ParenExpr* x)
    {
        return x->Rparen + 1;
    }

    token::Pos rec::End(SelectorExpr* x)
    {
        return rec::End(gocpp::recv(x->Sel));
    }

    token::Pos rec::End(IndexExpr* x)
    {
        return x->Rbrack + 1;
    }

    token::Pos rec::End(IndexListExpr* x)
    {
        return x->Rbrack + 1;
    }

    token::Pos rec::End(SliceExpr* x)
    {
        return x->Rbrack + 1;
    }

    token::Pos rec::End(TypeAssertExpr* x)
    {
        return x->Rparen + 1;
    }

    token::Pos rec::End(CallExpr* x)
    {
        return x->Rparen + 1;
    }

    token::Pos rec::End(StarExpr* x)
    {
        return rec::End(gocpp::recv(x->X));
    }

    token::Pos rec::End(UnaryExpr* x)
    {
        return rec::End(gocpp::recv(x->X));
    }

    token::Pos rec::End(BinaryExpr* x)
    {
        return rec::End(gocpp::recv(x->Y));
    }

    token::Pos rec::End(KeyValueExpr* x)
    {
        return rec::End(gocpp::recv(x->Value));
    }

    token::Pos rec::End(ArrayType* x)
    {
        return rec::End(gocpp::recv(x->Elt));
    }

    token::Pos rec::End(StructType* x)
    {
        return rec::End(gocpp::recv(x->Fields));
    }

    token::Pos rec::End(FuncType* x)
    {
        if(x->Results != nullptr)
        {
            return rec::End(gocpp::recv(x->Results));
        }
        return rec::End(gocpp::recv(x->Params));
    }

    token::Pos rec::End(InterfaceType* x)
    {
        return rec::End(gocpp::recv(x->Methods));
    }

    token::Pos rec::End(MapType* x)
    {
        return rec::End(gocpp::recv(x->Value));
    }

    token::Pos rec::End(ChanType* x)
    {
        return rec::End(gocpp::recv(x->Value));
    }

