    // NewIdent creates a new [Ident] without position.
    // Useful for ASTs generated by code other than the Go parser.
    Ident* NewIdent(gocpp::string name)
    {
        return new Ident {token::NoPos, name, nullptr};
    }

    // IsExported reports whether name starts with an upper-case letter.
    bool IsExported(gocpp::string name)
    {
        return token::IsExported(name);
    }

    // IsExported reports whether id starts with an upper-case letter.
    bool rec::IsExported(Ident* id)
    {
        return token::IsExported(id->Name);
    }

    gocpp::string rec::String(Ident* id)
    {
        if(id != nullptr)
        {
            return id->Name;
        }
        return "<nil>"_s;
    }

    // A statement is represented by a tree consisting of one
    // or more of the following concrete statement nodes.
    // A BadStmt node is a placeholder for statements containing
    // syntax errors for which no correct statement nodes can be
    // created.
    //
    // A DeclStmt node represents a declaration in a statement list.
    // An EmptyStmt node represents an empty statement.
    // The "position" of the empty statement is the position
    // of the immediately following (explicit or implicit) semicolon.
    //
    // A LabeledStmt node represents a labeled statement.
    // An ExprStmt node represents a (stand-alone) expression
    // in a statement list.
    //
    // A SendStmt node represents a send statement.
    // An IncDecStmt node represents an increment or decrement statement.
    // An AssignStmt node represents an assignment or
    // a short variable declaration.
    //
    // A GoStmt node represents a go statement.
    // A DeferStmt node represents a defer statement.
    // A ReturnStmt node represents a return statement.
    // A BranchStmt node represents a break, continue, goto,
    // or fallthrough statement.
    //
    // A BlockStmt node represents a braced statement list.
    // An IfStmt node represents an if statement.
    // A CaseClause represents a case of an expression or type switch statement.
    // A SwitchStmt node represents an expression switch statement.
    // A TypeSwitchStmt node represents a type switch statement.
    // A CommClause node represents a case of a select statement.
    // A SelectStmt node represents a select statement.
    // A ForStmt represents a for statement.
    // A RangeStmt represents a for statement with a range clause.
    
    template<typename T> requires gocpp::GoStruct<T>
    BadStmt::operator T()
    {
        T result;
        result.From = this->From;
        result.To = this->To;
        return result;
    }

    template<typename T> requires gocpp::GoStruct<T>
    bool BadStmt::operator==(const T& ref) const
    {
        if (From != ref.From) return false;
        if (To != ref.To) return false;
        return true;
    }

    std::ostream& BadStmt::PrintTo(std::ostream& os) const
    {
        os << '{';
        os << "" << From;
        os << " " << To;
        os << '}';
        return os;
    }

    std::ostream& operator<<(std::ostream& os, const struct BadStmt& value)
    {
        return value.PrintTo(os);
    }

    
