    token::Pos rec::Pos(CommClause* s)
    {
        return s->Case;
    }

    token::Pos rec::Pos(SelectStmt* s)
    {
        return s->Select;
    }

    token::Pos rec::Pos(ForStmt* s)
    {
        return s->For;
    }

    token::Pos rec::Pos(RangeStmt* s)
    {
        return s->For;
    }

    token::Pos rec::End(BadStmt* s)
    {
        return s->To;
    }

    token::Pos rec::End(DeclStmt* s)
    {
        return rec::End(gocpp::recv(s->Decl));
    }

    token::Pos rec::End(EmptyStmt* s)
    {
        if(s->Implicit)
        {
            return s->Semicolon;
        }
        // len(";")
        return s->Semicolon + 1;
    }

    token::Pos rec::End(LabeledStmt* s)
    {
        return rec::End(gocpp::recv(s->Stmt));
    }

    token::Pos rec::End(ExprStmt* s)
    {
        return rec::End(gocpp::recv(s->X));
    }

    token::Pos rec::End(SendStmt* s)
    {
        return rec::End(gocpp::recv(s->Value));
    }

    token::Pos rec::End(IncDecStmt* s)
    {
        // len("++")
        return s->TokPos + 2;
    }

    token::Pos rec::End(AssignStmt* s)
    {
        return rec::End(gocpp::recv(s->Rhs[len(s->Rhs) - 1]));
    }

    token::Pos rec::End(GoStmt* s)
    {
        return rec::End(gocpp::recv(s->Call));
    }

    token::Pos rec::End(DeferStmt* s)
    {
        return rec::End(gocpp::recv(s->Call));
    }

    token::Pos rec::End(ReturnStmt* s)
    {
        if(auto n = len(s->Results); n > 0)
        {
            return rec::End(gocpp::recv(s->Results[n - 1]));
        }
        // len("return")
        return s->Return + 6;
    }

    token::Pos rec::End(BranchStmt* s)
    {
        if(s->Label != nullptr)
        {
            return rec::End(gocpp::recv(s->Label));
        }
        return token::Pos(int(s->TokPos) + len(rec::String(gocpp::recv(s->Tok))));
    }

    token::Pos rec::End(BlockStmt* s)
    {
        if(rec::IsValid(gocpp::recv(s->Rbrace)))
        {
            return s->Rbrace + 1;
        }
        if(auto n = len(s->List); n > 0)
        {
            return rec::End(gocpp::recv(s->List[n - 1]));
        }
        return s->Lbrace + 1;
    }

    token::Pos rec::End(IfStmt* s)
    {
        if(s->Else != nullptr)
        {
            return rec::End(gocpp::recv(s->Else));
        }
        return rec::End(gocpp::recv(s->Body));
    }

    token::Pos rec::End(CaseClause* s)
    {
        if(auto n = len(s->Body); n > 0)
        {
            return rec::End(gocpp::recv(s->Body[n - 1]));
        }
        return s->Colon + 1;
    }

    token::Pos rec::End(SwitchStmt* s)
    {
        return rec::End(gocpp::recv(s->Body));
    }

    token::Pos rec::End(TypeSwitchStmt* s)
    {
        return rec::End(gocpp::recv(s->Body));
    }

    token::Pos rec::End(CommClause* s)
    {
        if(auto n = len(s->Body); n > 0)
        {
            return rec::End(gocpp::recv(s->Body[n - 1]));
        }
        return s->Colon + 1;
    }

    token::Pos rec::End(SelectStmt* s)
    {
        return rec::End(gocpp::recv(s->Body));
    }

    token::Pos rec::End(ForStmt* s)
    {
        return rec::End(gocpp::recv(s->Body));
    }

    token::Pos rec::End(RangeStmt* s)
    {
        return rec::End(gocpp::recv(s->Body));
    }

