    // A Spec node represents a single (non-parenthesized) import,
    // constant, type, or variable declaration.
    // The Spec type stands for any of *ImportSpec, *ValueSpec, and *TypeSpec.
    // An ImportSpec node represents a single package import.
    // A ValueSpec node represents a constant or variable declaration
    // (ConstSpec or VarSpec production).
    //
    // A TypeSpec node represents a type declaration (TypeSpec production).
    
    template<typename T>
    Spec::Spec(T& ref)
    {
        mValue.reset(new SpecImpl<T, std::unique_ptr<T>>(new T(ref)));
    }

    template<typename T>
    Spec::Spec(const T& ref)
    {
        mValue.reset(new SpecImpl<T, std::unique_ptr<T>>(new T(ref)));
    }

    template<typename T>
    Spec::Spec(T* ptr)
    {
        mValue.reset(new SpecImpl<T, gocpp::ptr<T>>(ptr));
    }

    std::ostream& Spec::PrintTo(std::ostream& os) const
    {
        return os;
    }

    template<typename T, typename TStore, typename TInterface>
    void Spec::SpecImpl<T, TStore, TInterface>::vspecNode()
    {
        return rec::specNode(gocpp::PtrRecv<T, false>(value.get()));
    }

    inline Spec::ISpec* Spec::value() const
    {
        if(auto res = mValue.get()) { return res; }
        throw gocpp::GoPanic("using nil value for interface 'Spec'");
    }

    namespace rec
    {
        void specNode(const gocpp::PtrRecv<struct Spec, false>& self)
        {
            return self.ptr->value()->vspecNode();
        }

        void specNode(const gocpp::ObjRecv<struct Spec>& self)
        {
            return self.obj.value()->vspecNode();
        }

        token::Pos End(const gocpp::PtrRecv<struct Spec, false>& self)
        {
            return self.ptr->value()->vEnd();
        }

        token::Pos End(const gocpp::ObjRecv<struct Spec>& self)
        {
            return self.obj.value()->vEnd();
        }

        token::Pos Pos(const gocpp::PtrRecv<struct Spec, false>& self)
        {
            return self.ptr->value()->vPos();
        }

        token::Pos Pos(const gocpp::ObjRecv<struct Spec>& self)
        {
            return self.obj.value()->vPos();
        }
    }

    std::ostream& operator<<(std::ostream& os, const struct Spec& value)
    {
        return value.PrintTo(os);
    }

    
    template<typename T> requires gocpp::GoStruct<T>
    ImportSpec::operator T()
    {
        T result;
        result.Doc = this->Doc;
        result.Name = this->Name;
        result.Path = this->Path;
        result.Comment = this->Comment;
        result.EndPos = this->EndPos;
        return result;
    }

    template<typename T> requires gocpp::GoStruct<T>
    bool ImportSpec::operator==(const T& ref) const
    {
        if (Doc != ref.Doc) return false;
        if (Name != ref.Name) return false;
        if (Path != ref.Path) return false;
        if (Comment != ref.Comment) return false;
        if (EndPos != ref.EndPos) return false;
        return true;
    }

    std::ostream& ImportSpec::PrintTo(std::ostream& os) const
    {
        os << '{';
        os << "" << Doc;
        os << " " << Name;
        os << " " << Path;
        os << " " << Comment;
        os << " " << EndPos;
        os << '}';
        return os;
    }

    std::ostream& operator<<(std::ostream& os, const struct ImportSpec& value)
    {
        return value.PrintTo(os);
    }

    
