    token::Pos rec::Pos(ImportSpec* s)
    {
        if(s->Name != nullptr)
        {
            return rec::Pos(gocpp::recv(s->Name));
        }
        return rec::Pos(gocpp::recv(s->Path));
    }

    token::Pos rec::Pos(ValueSpec* s)
    {
        return rec::Pos(gocpp::recv(s->Names[0]));
    }

    token::Pos rec::Pos(TypeSpec* s)
    {
        return rec::Pos(gocpp::recv(s->Name));
    }

    token::Pos rec::End(ImportSpec* s)
    {
        if(s->EndPos != 0)
        {
            return s->EndPos;
        }
        return rec::End(gocpp::recv(s->Path));
    }

    token::Pos rec::End(ValueSpec* s)
    {
        if(auto n = len(s->Values); n > 0)
        {
            return rec::End(gocpp::recv(s->Values[n - 1]));
        }
        if(s->Type != nullptr)
        {
            return rec::End(gocpp::recv(s->Type));
        }
        return rec::End(gocpp::recv(s->Names[len(s->Names) - 1]));
    }

    token::Pos rec::End(TypeSpec* s)
    {
        return rec::End(gocpp::recv(s->Type));
    }

