    token::Pos rec::End(BadDecl* d)
    {
        return d->To;
    }

    token::Pos rec::End(GenDecl* d)
    {
        if(rec::IsValid(gocpp::recv(d->Rparen)))
        {
            return d->Rparen + 1;
        }
        return rec::End(gocpp::recv(d->Specs[0]));
    }

    token::Pos rec::End(FuncDecl* d)
    {
        if(d->Body != nullptr)
        {
            return rec::End(gocpp::recv(d->Body));
        }
        return rec::End(gocpp::recv(d->Type));
    }

